CREATE TABLE market_prices (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    stock_id BIGINT NOT NULL REFERENCES stocks(id),
    price_interval VARCHAR(10) NOT NULL,
    open_price NUMERIC(20, 4) NOT NULL,
    high_price NUMERIC(20, 4) NOT NULL,
    low_price NUMERIC(20, 4) NOT NULL,
    close_price NUMERIC(20, 4) NOT NULL,
    volume NUMERIC(24, 4) NOT NULL,
    recorded_at TIMESTAMP WITH TIME ZONE NOT NULL,
    source VARCHAR(50) NOT NULL,
    CONSTRAINT uk_market_prices_stock_interval_time UNIQUE (stock_id, price_interval, recorded_at)
);

CREATE INDEX idx_market_prices_stock_recorded_at
    ON market_prices (stock_id, recorded_at DESC);

